import { readFileSync } from "node:fs";
import { basename, dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { deep } from "./sub/deep.js";

const here = dirname(fileURLToPath(import.meta.url));
export function where() {
  return [
    basename(fileURLToPath(import.meta.url)),
    import.meta.dirname === here,
    import.meta.filename === join(here, "index.js"),
    relative(here, fileURLToPath(new URL("./sub/deep.js", import.meta.url))),
    relative(here, fileURLToPath(import.meta.resolve("./sub/deep.js"))),
    deep(here),
    readFileSync(join(here, "data.txt"), "utf8").trim(),
  ].join(" ");
}
